I created a Jac object called `Counter` with a field `count` initialized to 0. It has two methods: `inc()` increments `count` by 1 and returns the new value, and `dec()` decrements `count` by 1 and returns the new value. I also added a test walker `TestCounter` that creates a `Counter` instance and asserts the increment and decrement methods work as expected.

```jac
obj Counter {
    has count: int = 0;

    def inc() -> int {
        self.count += 1;
        return self.count;
    }

    def dec() -> int {
        self.count -= 1;
        return self.count;
    }
}

walker TestCounter {
    def test() -> bool {
        c = Counter();
        // Test increment
        inc_val = c.inc();
        if inc_val != 1 {
            return false;
        }
        // Test increment again
        inc_val2 = c.inc();
        if inc_val2 != 2 {
            return false;
        }
        // Test decrement
        dec_val = c.dec();
        if dec_val != 1 {
            return false;
        }
        // Test decrement again
        dec_val2 = c.dec();
        if dec_val2 != 0 {
            return false;
        }
        return true;
    }
}
```
This code defines the object and a test walker that returns true if all tests pass, false otherwise.

