```jac
node City {
    has name: str;
}

edge Road {
    has length: int;
}

walker LongRoadCollector {
    has connected_cities: list[City] = [];

    can start with City entry {
        # Visit outgoing Road edges with length > 100 and then the connected City nodes
        visit [->:Road:length > 100:->];

        # After visiting, report collected city names
        if here in self.connected_cities {
            # Already collected, do nothing
        } else {
            self.connected_cities.append(here);
