    can finish with City exit {
        # Only report once when finishing the start node
        if self.connected_cities {
            for city in self.connected_cities {
                print(city.name);
            }
            report self.connected_cities;
        }
    }
}

with entry {
    # Create three cities
    city1 = City(name="Alpha");
    city2 = City(name="Beta");
    city3 = City(name="Gamma");

