            # Visit the newly created node to set it as unique_item
            visit self.unique_item;
        }
    }

    can start with UniqueItem entry {
        # If visiting a UniqueItem, record it
        self.unique_item = here;
    }

    can finish with Root exit {
        # Report the unique item node found or created
        report self.unique_item;
    }
}
```

