I created a generic Stack[T] object with append and pop methods without explicit self. Then I created a stack of strings, appended three names, popped one, and printed the result.

```jac
# Generic Stack object with type parameter T
obj Stack[T] {
    has items: list[T] = [];

    # Append method adds an element to the stack
    def append(item: T) -> None {
        items = items + [item];
    }

    # Pop method removes and returns the last element
    def pop() -> T {
        if len(items) == 0 {
            return null;
        }
        last = items[-1];
        items = items[:-1];
        return last;
    }
}

with entry {
    # Create a stack of strings
    stack = Stack[str]();

    # Append three names
    stack.append("Alice");
    stack.append("Bob");
    stack.append("Charlie");

    # Pop one name
    popped_name = stack.pop();

    # Print the popped name and the remaining stack
    print("Popped name: " + popped_name);
    print("Remaining stack: " + str(stack.items));
}
```

