```jac
node City {
    has name: str;
}

edge Road {
    has length: int;
}

with entry {
    # Create three cities
    city1 = root ++> City(name="CityA");
    city2 = root ++> City(name="CityB");
    city3 = root ++> City(name="CityC");

    # Connect cities with roads of varying lengths
    city1 ++> city2 via Road(length=150);
    city2 ++> city3 via Road(length=90);
    city1 ++> city3 via Road(length=200);

    # Spawn the walker starting from city1
    result = city1 spawn CityCollector();

    # Print collected city names from reports
    print("Collected cities with roads > 100 length:");
    for name in result.reports {
        print(name);
    }
}

walker CityCollector {
    has collected: list = [];

    can collect with City entry {
        # Traverse outgoing Road edges with length > 100
        visit [->:Road:length > 100:->] else {
            # No connected cities with road length > 100
            disengage;
        };

        # Filter to City nodes only
        visit [?:City] else {
            disengage;
        };

        # For each connected city, print and collect the name
        print(f"Connected city: {here.name}");
        self.collected.append(here.name);
        report here.name;

        # Do not continue traversal further
        disengage;
    }
}
```
