```jac
with entry {
    // Expression 1: (1 + 2) * 3 ** 2
    // Explanation: Exponentiation (**) has higher precedence than multiplication (*),
    // so 3 ** 2 is evaluated first, then multiplied by (1 + 2).
    expr1 = (1 + 2) * 3 ** 2;
    print(f"(1 + 2) * 3 ** 2 = {expr1}  // 3 ** 2 evaluated first, then multiplied by (1 + 2)");

    // Expression 2: not False and True or False
    // Explanation: not has the highest precedence, then and, then or.
    expr2 = not False and True or False;
    print(f"not False and True or False = {expr2}  // 'not' evaluated first, then 'and', then 'or'");

    // Expression 3: 4 << 1 + 1
    // Explanation: Addition (+) has higher precedence than bitwise shift (<<),
    // so 1 + 1 is evaluated first, then 4 is shifted left by that result.
    expr3 = 4 << 1 + 1;
    print(f"4 << 1 + 1 = {expr3}  // 1 + 1 evaluated first, then 4 shifted left by the result");

    // Expression 4: 5 < 10 == True
    // Explanation: Comparison operators chain, so this is equivalent to (5 < 10) and (10 == True).
    expr4 = 5 < 10 == True;
    print(f"5 < 10 == True = {expr4}  // Comparison chaining: (5 < 10) and (10 == True)");
}
```

