```jac
walker UniqueItemEnsurer {
    can start with Root entry {
        # Check for existing UniqueItem node connected from root
        unique_items = [here -->][?:UniqueItem];
        if unique_items.count() == 0 {
            # Create the UniqueItem node if missing
            unique_item = here ++> UniqueItem();
