    print(numbers);  # [10, 20, 50]

    # Append 60 by creating new list
    numbers = numbers + [60];
    print(numbers);  # [10, 20, 50, 60]

    # Insert 15 at index 1 by slicing and concatenation
    numbers = numbers[:1] + [15] + numbers[1:];
    print(numbers);  # [10, 15, 20, 50, 60]

    # Remove 20 by filtering
    numbers = [x for x in numbers if x != 20];
