```jac
with entry {
    # Expression 1: (1 + 2) * 3 ** 2
    # Explanation: Exponentiation (**) has higher precedence than multiplication (*),
    # so 3 ** 2 is evaluated first, then (1 + 2) is multiplied by the result.
    expr1 = (1 + 2) * 3 ** 2;
    print(f"(1 + 2) * 3 ** 2 = {expr1}  # Exponentiation before multiplication");

    # Expression 2: not False and True or False
    # Explanation: 'not' has the highest precedence, then 'and', then 'or'.
    # So 'not False' is True, then True and True is True, then True or False is True.
    expr2 = not False and True or False;
    print(f"not False and True or False = {expr2}  # not > and > or");

    # Expression 3: 4 << 1 + 1
    # Explanation: Addition (+) has higher precedence than bitwise shift (<<),
    # so 1 + 1 is evaluated first, then 4 is shifted left by that amount.
    expr3 = 4 << 1 + 1;
    print(f"4 << 1 + 1 = {expr3}  # Addition before bitwise shift");

    # Expression 4: 5 < 10 == True
    # Explanation: Comparison operators chain, so this means (5 < 10) and (10 == True).
    # The expression evaluates to False because 10 == True is False.
    expr4 = 5 < 10 == True;
    print(f"5 < 10 == True = {expr4}  # Comparison chaining");
}
```

