```jac
with entry {
    // Demonstrate operator precedence with explanations

    // (1 + 2) * 3 ** 2
    // Exponentiation (**) has higher precedence than multiplication (*),
    // so 3 ** 2 is evaluated first, then multiplied by (1 + 2).
    result1 = (1 + 2) * 3 ** 2;
    print("Expression (1 + 2) * 3 ** 2 evaluates to: " + result1);
    print("Explanation: Exponentiation (3 ** 2) evaluated before multiplication.");

    // not False and True or False
    // not has highest precedence, then and, then or.
    result2 = not False and True or False;
    print("Expression not False and True or False evaluates to: " + result2);
    print("Explanation: 'not False' evaluated first, then 'and True', then 'or False'.");

    // 4 << 1 + 1
    // Addition (+) has higher precedence than bitwise shift (<<),
    // so 1 + 1 is evaluated first, then 4 is shifted left by that amount.
    result3 = 4 << 1 + 1;
    print("Expression 4 << 1 + 1 evaluates to: " + result3);
    print("Explanation: Addition (1 + 1) evaluated before bitwise shift (<<).");

    // 5 < 10 == True
    // Comparison operators chain, so this is equivalent to (5 < 10) and (10 == True).
    result4 = 5 < 10 == True;
    print("Expression 5 < 10 == True evaluates to: " + result4);
    print("Explanation: Comparisons chain: (5 < 10) and (10 == True).");
}
```

