import from jaclang.byllm.lib { Model, by }

glob llm = Model(model_name="gpt-4o");

def subtract(a: int, b: int) -> int {
    return a - b;
}

def divide(a: float, b: float) -> float {
    return a / b;
}

def answer_42() -> int {
    return 42;
}

def solve_operation(query: str, conversation: list[dict]) -> str by llm(tools=[subtract, divide, answer_42], conversation=conversation);

with entry {
    conversation = [];

    res1 = solve_operation("What is 10 minus 4?", conversation);
    print(res1);

    res2 = solve_operation("Divide 9.0 by 3.0.", conversation);
    print(res2);

    res3 = solve_operation("What is the answer to life, the universe, and everything?", conversation);
    print(res3);
}
```
