```jac
walker SquareStats {
    can start with any entry {
        # Assume entry is a list of numbers
        squares = [];
        for num in entry {
            squares.append(num * num);
        }
        report squares;

        sum_squares = 0;
        for sq in squares {
            sum_squares += sq;
        }
        avg_squares = 0;
        if len(squares) > 0 {
            avg_squares = sum_squares / len(squares);
        }
        report {"sum": sum_squares, "average": avg_squares};
    }
}
```

