node Item {
    has name: str;
}

walker:priv CreateItem {
    has name: str;

    can create with Root entry {
        new_item = spawn Item(name=self.name);
        connect(here, new_item);
        report new_item;
    }
}

walker:priv ListItems {
    has items: list[Item] = [];
    reports: list[list[Item]] = [];

    can collect with Root entry {
        visit [-->];
    }

    can gather with Item entry {
        self.items.append(here);
    }

    can finish with Root exit {
        report self.items;
    }
}

with entry {
    created = CreateItem(name="Book")(Root());
    print(created.reports[0]);

    listed = ListItems()(Root());
    print(listed.reports[0]);
}
```

